void *ndpGetOption(uint8_t *options, size_t length, uint8_t type)
{
   size_t i;
   NdpOption *option;

   i = 0;

   while((i + sizeof(NdpOption)) <= length)
   {
      option = (NdpOption *) (options + i);

      if(option->length == 0)
