parse_field(netdissect_options *ndo, const char **pptr, int *len, int *truncated)
{
    const char *s;

    s = *pptr;
    for (;;) {
	if (*len == 0) {
	    return NULL;
	}
	if (!ND_TTEST(**pptr)) {
	    *truncated = 1;
