static void editPackageValue(int argc, char **argv)
{
    cchar   *key, *value;
    int     i;

    if (argc < 1) {
        usageError();
        return;
    }
    for (i = 0; i < argc; i++) {
        key = ssplit(sclone(argv[i]), "=", (char**) &value);
        if (value) {
            setPackageKey(key, value);
        } else {
            value = getConfigValue(key, 0);
            if (value) { 
                printf("%s\n", value);
            } else {
                printf("undefined\n");
            }
        }
    }
}

