{
    MprJson      *child;
    int         i, index;

    if (!obj || !name) {
        return 0;
    }
    if (obj->type & MPR_JSON_OBJ) {
        for (ITERATE_JSON(obj, child, i)) {
            if (smatch(child->name, name)) {
                return child;
            }
