		nmi_enter();
	else
		irq_enter();

	for (i = 0; i < ppmu->n_counter; ++i) {
		event = cpuhw->event[i];

		val = read_pmc(i);
		if ((int)val < 0) {
			if (event) {
				found = 1;
				record_and_restart(event, val, regs);
			} else {
				write_pmc(i, 0);
			}
		}
	}

